shell_commands:
node -e "
const fs = require('fs');
const path = require('path');
const pkgDir = path.dirname(require.resolve('@re-cinq/eslint-plugin-re-lint/package.json'));
console.log(fs.readdirSync(path.join(pkgDir, 'rules')).filter(f => f.includes('test') || f.includes('spec') || f.includes('duplicate')));
for (const f of ['require-colocated-tests.js', 'test-imports-its-subject.js', 'require-spec-link.js', 'no-duplicate-code.js']) {
  const p = path.join(pkgDir, 'rules', f);
  if (fs.existsSync(p)) {
    console.log('=== ' + f + ' ===');
    console.log(fs.readFileSync(p, 'utf8'));
  }
}
"

